import {FERRY_ART_STAGES} from './ferry-art.js';
import {FLEET_BOATS,FLEET_ROUTES,LIGHTHOUSE_STAGES,berthCount} from './engine.js';
import {COAST_PROJECT_CLIPS,COAST_BERTHS,COAST_DESTINATIONS,COAST_BERTH_ROUTES,LIGHTHOUSE_PLOT} from './coast-map.js';
import {fleetHull} from './fleet-ui.js';

// Interpolate by path length so ships keep a steady apparent speed.
export function coastPosition(points,fraction){
 const lengths=points.slice(1).map((p,i)=>Math.hypot(p[0]-points[i][0],p[1]-points[i][1])),total=lengths.reduce((a,b)=>a+b,0);let left=Math.max(0,Math.min(1,fraction))*total;
 for(let i=0;i<lengths.length;i++){if(left<=lengths[i]||i===lengths.length-1){const f=lengths[i]?left/lengths[i]:0,a=points[i],b=points[i+1];return {x:a[0]+(b[0]-a[0])*f,y:a[1]+(b[1]-a[1])*f,angle:Math.atan2(b[1]-a[1],b[0]-a[0])*180/Math.PI};}left-=lengths[i];}
 return {x:points[0][0],y:points[0][1],angle:0};
}
// Circuits visit each landing once, then return home. Single trips retain their out-and-back path.
export function coastTripPath(trip,slot){
 const outward=COAST_BERTH_ROUTES[trip.route][slot];
 if(!trip.stops)return [...outward,...outward.slice(0,-1).reverse()];
 const last=trip.stops[1].route,back=COAST_BERTH_ROUTES[last][slot];
 const bridge=trip.route==='quarry'?[[610,340],[670,470],[660,590]]:[[660,590],[670,470],[610,340]];
 return [...outward,...bridge,...[...back].reverse()];
}
export function coastMapView(s){const l=s.fleet.lighthouse;return `${s.ferry?.stage?`<div class="coast-ferry" style="clip-path:${FERRY_ART_STAGES[s.ferry.stage-1].clip}" aria-hidden="true"></div>`:""}${s.neighbourhood?.access?`<button class="map-pin ferry-map-pin" style="left:87%;top:60%" data-action="go-ferry"><span>Ferry terminal<small>${s.ferry.stage===3?"Passenger services":s.ferry.stage+" / 3 stages"}</small></span></button>`:""}${Object.entries(COAST_PROJECT_CLIPS).map(([route,clips])=>clips.slice(0,s.fleet.development?.[route]||0).map(clip=>`<div class="coast-developed" style="clip-path:${clip}" aria-hidden="true"></div>`).join('')).join('')}${l.stage?`<div class="coast-restored" style="clip-path:${LIGHTHOUSE_PLOT.stagedClips[l.stage-1]}" aria-hidden="true"></div>`:''}<svg class="coast-routes" viewBox="0 0 1536 1024" aria-hidden="true">${s.fleet.boats.map((b,slot)=>b?.trip?`<polyline points="${coastTripPath(b.trip,slot).map(p=>p.join(',')).join(' ')}" fill="none" stroke="#f4ecd1" stroke-width="3" stroke-dasharray="9 12" opacity=".55"/>`:'').join('')}</svg>${Object.entries(COAST_DESTINATIONS).map(([key,p])=>`<button class="map-pin coast-destination" style="left:${p.pin.x}%;top:${p.pin.y}%" data-action="fleet-destination" data-key="${key}"><span class="pin-icon">${key==='quarry'?'◇':'⚓'}</span><span>${FLEET_ROUTES[key].name}<small>${s.fleet.visits[key]} voyages · ${s.fleet.development?.[key]||0}/3 projects</small></span></button>`).join('')}<button class="map-pin lighthouse-pin" style="left:${LIGHTHOUSE_PLOT.x}%;top:${LIGHTHOUSE_PLOT.y+8}%" data-action="fleet-view" data-key="lighthouse"><span class="pin-icon">☀</span><span>Lighthouse<small>${l.left?'Crew on site':l.stage===3?'Beacon lit · two berths':l.stage+' / 3 stages restored'}</small></span></button>${l.left?`<div class="market-work coast-work" style="left:${LIGHTHOUSE_PLOT.x}%;top:${LIGHTHOUSE_PLOT.y}%"><span class="work-frame"></span><small data-lighthouse-time></small></div>`:''}${l.stage===3?`<i class="lighthouse-glow" style="left:${LIGHTHOUSE_PLOT.lantern.x/1536*100}%;top:${LIGHTHOUSE_PLOT.lantern.y/1024*100}%" aria-hidden="true"></i>`:''}${COAST_BERTHS.map((p,slot)=>{const b=s.fleet.boats[slot];return `<button class="map-pin berth-pin" style="left:${p.x+14}%;top:${p.y}%" data-action="fleet-boat" data-slot="${slot}"><span>Berth ${slot+1}<small>${slot>=berthCount(s)?'Lighthouse needed':b?b.trip?'At sea':FLEET_BOATS[b.type].name:'Choose boat'}</small></span></button>${b?`<button class="coast-boat ${b.type}" data-coast-boat="${slot}" data-action="fleet-boat" data-slot="${slot}" style="left:${p.x}%;top:${p.y}%" aria-label="Berth ${slot+1}: ${FLEET_BOATS[b.type].name}${b.trip?' sailing to '+FLEET_ROUTES[b.trip.route].name:' in harbour'}">${fleetHull(b.type)}<span>${slot+1}</span></button>`:''}`;}).join('')}`;}
